def generate_image(model_id, prompt, output_path):
    """Generate an image using OpenRouter API and save it to a file."""
    url = "https://openrouter.ai/api/v1/chat/completions"
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json"
    }
    data = {
        "model": model_id,
        "messages": [
            {"role": "user", "content": prompt}
        ],
        "stream": False
    }

    print(f"\n{'='*60}")
    print(f"Model: {model_id}")
    print(f"Prompt: {prompt}")
    print(f"{'='*60}")

    try:
        response = requests.post(url, json=data, headers=headers, timeout=180)
        print(f"Status: {response.status_code}")

        if response.status_code == 200:
            try:
                result = response.json()
                print(f"✓ Success! Response contains {len(result)} keys")

                # Extract the image data
                if 'choices' in result and isinstance(result['choices'], list) and result['choices']:
                    for i, choice in enumerate(result['choices']):
                        message = choice.get('message', {})
                        images = message.get('images', [])

                        if images:
                            for j, img in enumerate(images):
                                img_url = img.get('image_url', {}).get('url', '')
                                if img_url.startswith('data:image/png;base64,'):
                                    # Extract base64 data
                                    base64_data = img_url.split(',')[1]
                                    # Save to file
                                    with open(output_path, 'wb') as f:
                                        f.write(base64.b64decode(base64_data))
                                    print(f"✓ Image saved to: {output_path}")
                                    return True
                                else:
                                    print(f"  Image {j}: Unexpected format")
                        else:
                            print("✗ No images in response")
                else:
                    print("✗ No 'choices' field or it's empty")
            except ValueError as e:
                print(f"✗ JSON decode error: {e}")
                print(f"First 200 chars: {response.text[:200]}")
        else:
            print(f"✗ Error: {response.text[:200]}")

    except Exception as e:
        print(f"✗ Request failed: {e}")

    return False

# Retry Book 4 with a simpler prompt and longer timeout
generate_image(
    model_id="openai/gpt-5.4-image-2",
    prompt="Book cover: Cosmic, ethereal, transcendent evolution. Title: 'Second Generation' at the top, author name 'Robert Mills' at the bottom.",
